function cMaterial(color,mode='standard',wear=0){const p={color,roughness:cl(.58+wear*.16),metalness:.04,flatShading:true};if(mode==='matte')p.roughness=1;if(mode==='metal'){p.metalness=.88;p.roughness=.25+wear*.15}if(mode==='glass'){p.transparent=true;p.opacity=.36;p.metalness=.12;p.roughness=.12;p.depthWrite=false}if(mode==='emissive'){p.emissive=color;p.emissiveIntensity=1.5}const material=mode==='toon'?new THREE.MeshToonMaterial({color}):new THREE.MeshStandardMaterial(p);if(!color?.isColor){material.color.convertSRGBToLinear();if(material.emissive)material.emissive.convertSRGBToLinear()}return material}
function cMesh(parent,name,geometry,material,pos=[0,0,0],rot=[0,0,0]){const m=new THREE.Mesh(geometry,material);m.name=name;m.position.set(...pos);m.rotation.set(...rot);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
