function cBall(p,n,d,m,xyz){const x=cMesh(p,n,new THREE.SphereGeometry(1,12,8),m,xyz);x.scale.set(...d);return x}
function cCylinder(p,n,rt,rb,h,m,xyz,rot){return cMesh(p,n,new THREE.CylinderGeometry(rt,rb,h,12),m,xyz,rot)}
function cJoint(p,name,xyz=[0,0,0],bone=false){const o=bone?new THREE.Bone():new THREE.Group();o.name=name;o.position.set(...xyz);o.userData.motion=name;p.add(o);return o}
