function validateCatalogScenario(j,w,fl){const err=s=>w.push('ERROR: '+s),obj=v=>v&&typeof v==='object'&&!Array.isArray(v),finite=n=>typeof n==='number'&&Number.isFinite(n),vec=v=>Array.isArray(v)&&v.length===3&&v.every(finite),range=(o,k,a,b,p)=>{if(o?.[k]!==undefined&&(!finite(o[k])||o[k]<a||o[k]>b))err(p+'.'+k+' must be '+a+'…'+b)};if(j.schema_version!==undefined&&j.schema_version!==7)err('schema_version must be 7.');if(j.world?.biome&&!['city','coast','ocean','sky','jungle','island','custom'].includes(j.world.biome))err('Unknown world.biome.');if(j.assets!==undefined&&!Array.isArray(j.assets))err('assets must be an array.');const map=new Map();if(Array.isArray(j.assets)){if(j.assets.length>250)err('Use at most 250 placed catalog assets per scene; the catalog is loaded on demand.');j.assets.forEach((s,i)=>{const p='assets['+i+']';if(!obj(s)){err(p+' must be an object.');return}if(typeof s.instance_id!=='string'||!/^[A-Za-z][A-Za-z0-9_-]{0,63}$/.test(s.instance_id))err(p+'.instance_id needs a letter followed by letters, digits, _ or -.');else if(map.has(s.instance_id))err('Duplicate instance_id '+s.instance_id);for(const key of Object.keys(s))if(!['instance_id','asset_id','name','position','rotation','scale','state','expression','accessories','shader','path','orient_to_path','visible'].includes(key))err(p+': unknown property '+key);const resolved=resolveCatalog(s.asset_id);if(!resolved)err(p+'.asset_id is unknown: '+String(s.asset_id));map.set(s.instance_id,resolved);for(const k of['position','rotation','scale'])if(s[k]!==undefined&&(!vec(s[k])||s[k].some(n=>Math.abs(n)>10000)||k==='scale'&&s[k].some(n=>n<=0||n>100)))err(p+'.'+k+' must be a finite XYZ triple within range.');if(s.state!==undefined&&resolved&&!resolved.base.states.includes(s.state))err(p+': unsupported state '+s.state);if(s.expression!==undefined&&(!resolved?.base.expressions.includes(s.expression)))err(p+': unsupported expression '+s.expression);if(s.shader!==undefined&&!MATERIAL_MODES.includes(s.shader))err(p+': unsupported shader '+s.shader);if(s.accessories!==undefined&&(!Array.isArray(s.accessories)||s.accessories.some(a=>!resolved?.base.accessories.includes(a))))err(p+': unsupported accessories.');if(s.name!==undefined&&typeof s.name!=='string')err(p+'.name must be text.');for(const k of['visible','orient_to_path'])if(s[k]!==undefined&&typeof s[k]!=='boolean')err(p+'.'+k+' must be boolean.');if(s.path!==undefined){if(!Array.isArray(s.path)||s.path.length<2||s.path.length>100)err(p+'.path needs 2…100 time/position points.');else s.path.forEach((point,n)=>{if(!obj(point)||!finite(point.t)||point.t<0||!vec(point.position)||n&&point.t<=s.path[n-1].t)err(p+'.path has an invalid point/time.');})}})}
 for(const [i,s] of fl.entries()){if(s.actions!==undefined&&!Array.isArray(s.actions)){err('Shot '+(i+1)+'.actions must be an array.');continue}const seen=new Set();for(const a of s.actions||[]){if(!obj(a)){err('Shot action must be an object.');continue}for(const key of Object.keys(a))if(!['target','state','expression','transition'].includes(key))err('Unknown shot action property '+key);const r=map.get(a.target);if(!r){err('Shot action target not found: '+a.target);continue}if(seen.has(a.target))err('Only one action per target per shot.');seen.add(a.target);if(a.state!==undefined&&!r.base.states.includes(a.state))err('Unsupported '+a.state+' for '+a.target);if(a.expression!==undefined&&!r.base.expressions.includes(a.expression))err('Unsupported expression for '+a.target);range(a,'transition',0,5,'action')}if(s.cam?.target_id!==undefined&&!map.has(s.cam.target_id))err('Camera target_id not found: '+s.cam.target_id);if(s.cam?.offset!==undefined&&(!vec(s.cam.offset)||s.cam.offset.every(n=>n===0)))err('cam.offset needs a nonzero XYZ vector.');range(s.cam,'target_height',-1000,1000,'cam');checkShotFields(s,i,w,err,range,vec)}
 const e=j.environment;if(e!==undefined){if(!obj(e)){err('environment must be an object.');return}for(const k of['sun','moon','clouds','water','fog'])if(e[k]!==undefined&&!obj(e[k]))err('environment.'+k+' must be an object.');for(const k of['sun','moon'])if(e[k]?.enabled!==undefined&&typeof e[k].enabled!=='boolean')err(k+'.enabled must be boolean.');range(e.sun,'azimuth',-360,360,'sun');range(e.sun,'elevation',-90,90,'sun');range(e.sun,'intensity',0,5,'sun');range(e.moon,'phase',0,1,'moon');range(e.moon,'intensity',0,3,'moon');range(e.clouds,'coverage',0,1,'clouds');range(e.clouds,'speed',-20,20,'clouds');range(e,'wind',0,5,'environment');range(e.water,'level',-100,100,'water');range(e.water,'wave_height',0,5,'water');range(e.water,'speed',0,5,'water');if(e.water?.color!==undefined&&!/^#[0-9a-f]{6}$/i.test(e.water.color))err('water.color must be #rrggbb.');range(e.fog,'near',0,1000,'fog');range(e.fog,'far',1,2000,'fog');if((e.fog?.far??520)<=(e.fog?.near??160))err('fog.far must exceed fog.near.')}
}

function sampleCatalogPath(points,t){let i=0;while(i<points.length-2&&t>points[i+1].t)i++;const a=points[i],b=points[i+1],pa=V(...a.position),pb=V(...b.position),u=cl((t-a.t)/(b.t-a.t)),delta=pb.clone().sub(pa);return{position:pa.lerp(pb,sm(u)),yaw:Math.atan2(delta.x,delta.z)}}

